alter table public.locations add column if not exists verification_observation_count integer not null default 0; alter table public.locations add column if not exists verification_positive_count integer not null default 0; alter table public.locations add column if not exists verification_negative_count integer not null default 0; alter table public.locations add column if not exists verification_confidence numeric not null default 0; create or replace function public.refresh_location_verification_summary(p_location_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v_total integer; v_positive integer; v_negative integer; begin select count(*), count(*) filter (where is_open=true and is_public=true), count(*) filter (where is_open=false or is_public=false) into v_total,v_positive,v_negative from public.location_verification_observations where location_id=p_location_id; update public.locations set verification_observation_count=v_total, verification_positive_count=v_positive, verification_negative_count=v_negative, verification_confidence=case when v_total=0 then 0 else round((v_positive::numeric/v_total::numeric),3) end, verified=case when v_total>=2 and v_positive>=2 and v_negative=0 then true else verified end where id=p_location_id; end; $$; create or replace function public.trg_refresh_location_verification_summary() returns trigger language plpgsql security definer set search_path=public as $$ begin perform public.refresh_location_verification_summary(coalesce(new.location_id,old.location_id)); return coalesce(new,old); end; $$; drop trigger if exists refresh_location_verification_summary on public.location_verification_observations; create trigger refresh_location_verification_summary after insert or update or delete on public.location_verification_observations for each row execute function public.trg_refresh_location_verification_summary();
